/**
 * Photo pipeline
 * ──────────────
 * Reads photos/photos.json, resizes + compresses every photo it lists, and
 * writes the results to public/gallery/ along with a manifest.json that the
 * game loads at runtime.
 *
 *   photos/            ← YOU edit this: original photos + photos.json
 *   public/gallery/    ← generated by this script, don't edit by hand
 *
 * Every photo becomes two small JPEGs:
 *   *.md.jpg  1024px long edge → the texture hanging on the museum wall
 *   *.lg.jpg  2048px long edge → the full-screen view (loaded only when opened)
 * Location/camera metadata (EXIF, GPS) is stripped from both.
 *
 * Runs automatically on `npm run dev` and `npm run build` (see vite.config.js).
 * You can also run it by hand:
 *   npm run photos               → optimize everything listed in photos.json
 *   npm run photos -- --add-new  → also append photos found in photos/ that
 *                                  aren't listed yet (then edit their texts)
 *
 * Unchanged photos are skipped (cached by content hash), so re-runs are fast.
 * iPhone HEIC photos are converted automatically on a Mac (via `sips`).
 */
import fs from 'node:fs/promises';
import { existsSync } from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import crypto from 'node:crypto';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { fileURLToPath } from 'node:url';
import sharp from 'sharp';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const PHOTOS_DIR = path.join(ROOT, 'photos');
const LIST_FILE = path.join(PHOTOS_DIR, 'photos.json');
const OUT_DIR = path.join(ROOT, 'public', 'gallery');

const SIZES = {
  md: { edge: 1024, quality: 80 },
  lg: { edge: 2048, quality: 82 },
};
// Bump this to force every photo to be regenerated (e.g. after changing SIZES).
const PIPELINE_VERSION = 1;
const IMAGE_EXT = new Set(['.jpg', '.jpeg', '.png', '.webp', '.heic', '.heif', '.avif', '.tif', '.tiff']);

/** Optimizes all photos and writes public/gallery/manifest.json. */
export async function buildGallery({ log = console.log, addNew = false } = {}) {
  let entries = await readList();
  if (addNew) entries = await appendUnlisted(entries, log);

  await fs.mkdir(OUT_DIR, { recursive: true });
  const existing = new Set(await fs.readdir(OUT_DIR));
  const keep = new Set(['manifest.json']);
  const manifest = [];
  let optimized = 0;

  for (const [i, entry] of entries.entries()) {
    if (!entry || typeof entry.file !== 'string') {
      log(`[photos] ⚠ entry #${i + 1} in photos.json has no "file" — skipped`);
      continue;
    }
    const stem = stemFor(entry.file);
    const src = path.join(PHOTOS_DIR, entry.file);
    let names;

    if (existsSync(src)) {
      const buf = await fs.readFile(src);
      const hash = crypto.createHash('sha1').update(buf).update(`v${PIPELINE_VERSION}`).digest('hex').slice(0, 8);
      names = { md: `${stem}.${hash}.md.jpg`, lg: `${stem}.${hash}.lg.jpg` };
      if (!existing.has(names.md) || !existing.has(names.lg)) {
        try {
          await optimize(src, names);
          optimized++;
        } catch (err) {
          log(`[photos] ⚠ could not process ${entry.file}: ${err.message}`);
          continue;
        }
      }
    } else {
      // The original isn't here (e.g. on a build server where originals are
      // git-ignored). Reuse a previously generated version if there is one.
      const re = new RegExp(`^${stem}\\.[0-9a-f]{8}\\.md\\.jpg$`);
      const md = [...existing].find((f) => re.test(f));
      if (!md) {
        log(`[photos] ⚠ photos/${entry.file} not found — skipped (check the "file" name in photos.json)`);
        continue;
      }
      names = { md, lg: md.replace(/\.md\.jpg$/, '.lg.jpg') };
    }

    keep.add(names.md);
    keep.add(names.lg);
    const mdPath = path.join(OUT_DIR, names.md);
    const { width, height } = await sharp(mdPath).metadata();
    const { dominant } = await sharp(mdPath).stats();
    manifest.push({
      src: `gallery/${names.md}`,
      full: `gallery/${names.lg}`,
      width,
      height,
      color: '#' + [dominant.r, dominant.g, dominant.b].map((v) => v.toString(16).padStart(2, '0')).join(''),
      room: entry.room ?? 1,
      title: entry.title ?? '',
      date: entry.date ?? '',
      caption: entry.caption ?? '',
    });
  }

  // Remove generated files that no longer belong to any photo.
  for (const f of existing) if (!keep.has(f)) await fs.rm(path.join(OUT_DIR, f), { force: true });

  await fs.writeFile(path.join(OUT_DIR, 'manifest.json'), JSON.stringify({ photos: manifest }, null, 2) + '\n');
  log(`[photos] ${manifest.length} photo(s) ready (${optimized} newly optimized, ${manifest.length - optimized} cached)`);
  return manifest;
}

async function readList() {
  let text;
  try {
    text = await fs.readFile(LIST_FILE, 'utf8');
  } catch {
    throw new Error('[photos] photos/photos.json is missing');
  }
  try {
    const list = JSON.parse(text);
    if (!Array.isArray(list)) throw new Error('it must be a list: [ {...}, {...} ]');
    return list;
  } catch (err) {
    // JSON errors are the most likely mistake when editing by hand — be helpful.
    throw new Error(`[photos] photos/photos.json has a typo: ${err.message}\n` +
      '         Tip: every entry needs quotes around texts and a comma between entries (but not after the last one).');
  }
}

/** Resizes one original into the two output sizes. */
async function optimize(src, names) {
  const input = await decodableInput(src);
  try {
    await Promise.all(Object.entries(SIZES).map(([key, { edge, quality }]) =>
      sharp(input)
        .rotate() // apply the phone's EXIF orientation
        .resize({ width: edge, height: edge, fit: 'inside', withoutEnlargement: true })
        .flatten({ background: '#ffffff' }) // transparent PNGs → white background
        .jpeg({ quality, mozjpeg: true, progressive: true })
        .toFile(path.join(OUT_DIR, names[key])),
    ));
  } finally {
    if (input !== src) await fs.rm(input, { force: true });
  }
}

/**
 * sharp's prebuilt binaries can't decode iPhone HEIC photos.
 * On a Mac, convert them to a temporary JPEG with the built-in `sips` tool.
 */
async function decodableInput(src) {
  const ext = path.extname(src).toLowerCase();
  if (ext !== '.heic' && ext !== '.heif') return src;
  try {
    await sharp(src).resize(8).toBuffer();
    return src;
  } catch {
    if (process.platform !== 'darwin') {
      throw new Error('HEIC photos can only be converted on a Mac — please export it as JPEG');
    }
    const tmp = path.join(os.tmpdir(), `museum-${crypto.randomUUID()}.jpg`);
    await promisify(execFile)('sips', ['-s', 'format', 'jpeg', '-s', 'formatOptions', '95', src, '--out', tmp]);
    return tmp;
  }
}

/** Filesystem-safe, unique name for generated files (works for any filename, Greek included). */
function stemFor(file) {
  const base = path.parse(file).name.normalize('NFKD').replace(/[^\w-]+/g, '-').replace(/^-+|-+$/g, '').toLowerCase();
  const id = crypto.createHash('sha1').update(file).digest('hex').slice(0, 6);
  return `${(base || 'photo').slice(0, 40)}-${id}`;
}

/** --add-new: append photos that are in photos/ but not in photos.json. */
async function appendUnlisted(entries, log) {
  const listed = new Set(entries.map((e) => e?.file));
  const files = (await fs.readdir(PHOTOS_DIR))
    .filter((f) => IMAGE_EXT.has(path.extname(f).toLowerCase()) && !listed.has(f))
    .sort();
  if (!files.length) {
    log('[photos] no new photos to add');
    return entries;
  }
  const lastRoom = entries.at(-1)?.room ?? 1;
  const added = files.map((file) => ({
    file,
    room: lastRoom,
    title: path.parse(file).name.replace(/[-_]+/g, ' '),
    date: '',
    caption: '',
  }));
  const next = [...entries, ...added];
  await fs.writeFile(LIST_FILE, JSON.stringify(next, null, 2) + '\n');
  log(`[photos] added ${added.length} new photo(s) to photos.json (room ${lastRoom}) — edit their room/title/date/caption`);
  return next;
}

// Run directly: `npm run photos` / `node scripts/photos.mjs [--add-new]`
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  buildGallery({ addNew: process.argv.includes('--add-new') }).catch((err) => {
    console.error(err.message);
    process.exit(1);
  });
}
